{"function": "() => {
  // Try to find the main content container
  const content = document.querySelector('article');
  if (!content) return null;
  // Find the element that contains the paragraphs and lists after the author info
  // The structure: article > generic > generic (with ref=e70) maybe
  // Let's just get all paragraphs and lists that are direct children of article's second generic? 
  // Actually, easier: get all text nodes within article but exclude the footer (the last generic with separator)
  const walker = document.createTreeWalker(content, NodeFilter.SHOW_TEXT, null, false);
  let text = '';
  while (walker.nextNode()) {
    const node = walker.currentNode;
    // Skip empty text nodes
    if (node.textContent.trim().length === 0) continue;
    // Check if node is inside the footer (contains "This page titled")
    if (node.textContent.includes('This page titled')) break;
    text += node.textContent + ' ';
  }
  return text.trim();
}"}

