  // Find the element that contains the exercises
  // The article has several generic children. The one after the author list likely has ref=e70
  // We can select by class? Let's try to find the element containing the paragraphs and lists.
  const article = document.querySelector('article');
  if (!article) return null;
  // Look for the element that contains the first paragraph starting with "Use the following paragraph"
  const walker = document.createTreeWalker(article, NodeFilter.SHOW_ELEMENT, null, false);
  let target = null;
  while (walker.nextNode()) {
    const node = walker.currentNode;
    if (node.textContent && node.textContent.includes('Use the following paragraph to answer the first two questions')) {
      target = node;
      break;
    }
  }
  if (!target) return article.innerText;
  // Now get all siblings until we reach the element containing "1.5: A Beginning Chemist"
  let content = '';
  let current = target;
  while (current) {
    // Check if we've reached the next section link
    if (current.textContent && current.textContent.includes('1.5: A Beginning Chemist')) {
      break;
    }
    content += current.innerText + '\n';
    current = current.nextElementSibling;
  }
  return content;
}"}

